            perror("gpiod_line_set_value GPIO 2");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, 0) < 0) {
            perror("gpiod_line_set_value GPIO 3");
            goto cleanup;
        }
        printf("GPIO 2: LOW, GPIO 3: LOW\n");
        fflush(stdout);

        sleep(5);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
