#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            "/dev/i2c-1"
#define MEASURE_CMD        0xF5
#define READ_INTERVAL_S    5
#define MAX_RETRIES        3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len)
{
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (device absent?)\n");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int read_temperature(int fd, float *temp_c)
{
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;

    /* Max conversion time for 14-bit temp is ~11 ms; give 20 ms */
    usleep(20000);

    uint8_t data[2];
    if (i2c_read_bytes(fd, data, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Quick presence check: try a zero-length write */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "SI7021 not responding at 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_temperature(fd, &temp) == 0) {
                ok = 1;
                break;
            }
            usleep(100000);
        }

        if (ok) {
            printf("Temperature: %.2f C\n", temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < READ_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADS1115_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"
#define NUM_READINGS 3
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Configuration register (0x01):
     *   Bit 15    OS: 1 = start single conversion
     *   Bits14:12 MUX: 100 = AIN0 vs GND
     *   Bits11:9  PGA: 001 = +/-4.096 V
     *   Bit 8     MODE: 1 = single-shot
     *   Bits7:5   DR: 100 = 128 SPS
     *   Bit 4     COMP_MODE: 0
     *   Bit 3     COMP_POL: 0
     *   Bit 2     COMP_LAT: 0
     *   Bits1:0   COMP_QUE: 11 = disable comparator
     *
     * 0x8483 = 1000 0100 1000 0011
     */
    if (i2c_write16(fd, 0x01, 0x8483) < 0) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_READINGS && g_running; i++) {
        /* Poll OS bit (bit 15) until it reads 1 (conversion complete) */
        uint16_t cfg;
        int poll_count = 0;
        int poll_ok = 0;
        do {
            if (i2c_read16(fd, 0x01, &cfg) < 0) {
                fprintf(stderr, "Failed to read config register: %s\n", strerror(errno));
                goto cleanup;
            }
            if (cfg & 0x8000) {
                poll_ok = 1;
                break;
            }
            usleep(10000); /* 10 ms */
            poll_count++;
            if (poll_count > 100) {
                fprintf(stderr, "Timeout waiting for conversion\n");
                goto cleanup;
            }
        } while (g_running);

        if (!g_running) {
            break;
        }
        if (!poll_ok) {
            break;
        }

        uint16_t raw;
        if (i2c_read16(fd, 0x00, &raw) < 0) {
            fprintf(stderr, "Failed to read conversion register: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Reading %d: %d\n", i + 1, (int16_t)raw);
        fflush(stdout);

        if (i < NUM_READINGS - 1 && g_running) {
            sleep(SAMPLE_INTERVAL_SEC);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 6
#define CYCLES 256
#define CONSUMER "digital_output"

static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
