    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < CYCLES && running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        for (int j = 0; j < NUM_PINS; j++) {
            if (gpiod_line_set_value(lines[j], val) < 0) {
                fprintf(stderr, "Failed to set line %u\n", pins[j]);
                goto cleanup;
            }
        }
        printf("Cycle %d: %s\n", i + 1, val ? "HIGH" : "LOW");
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
