static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static long measure(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0)
        return -1;
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0)
        return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0)
        return -1;

    /* Wait for echo rising edge (timeout) */
    int t0 = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (t0 >= TIMEOUT_US)
            return -1;
        usleep(1);
        t0++;
    }

    int t1 = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (t1 >= TIMEOUT_US)
            return -1;
        usleep(1);
        t1++;
    }

    return (long)t1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    while (running) {
        long d = measure(trig, echo);
        if (d < 0) {
            fprintf(stderr, "Error: sensor read failed (timeout or GPIO error)\n");
            goto cleanup;
        }
        printf("Distance: %ld us\n", d);
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

