#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_RETRIES 5
#define TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void delay_us(unsigned int us) {
    struct timespec ts = { us / 1000000, (long)(us % 1000000) * 1000 };
    nanosleep(&ts, NULL);
}

static int wait_for_level(struct gpiod_line *line, int level, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        delay_us(1);
        elapsed++;
        if (elapsed >= timeout_us) return -1;
    }
    return 0;
}

static int read_dht11(struct gpiod_line *line, int *humidity, int *temperature) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht11", 1) < 0) {
        fprintf(stderr, "Error: Failed to request line as output.\n");
        return -1;
    }

    gpiod_line_set_value(line, 0);
    delay_us(18000);
    gpiod_line_set_value(line, 1);
    delay_us(40);

    if (gpiod_line_request_input(line, "dht11") < 0) {
        fprintf(stderr, "Error: Failed to request line as input.\n");
        return -1;
    }

    if (wait_for_level(line, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: DHT11 not responding (no start signal).\n");
        return -1;
    }
    if (wait_for_level(line, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: DHT11 not responding (no response signal).\n");
        return -1;
    }
    if (wait_for_level(line, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: DHT11 not responding (no data start).\n");
        return -1;
    }

    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, TIMEOUT_US) < 0) {
            fprintf(stderr, "Error: Timeout waiting for bit %d high.\n", i);
            return -1;
        }
        unsigned int high_start = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (!running) return -1;
            delay_us(1);
            high_start++;
            if (high_start >= TIMEOUT_US) {
                fprintf(stderr, "Error: Timeout waiting for bit %d low.\n", i);
                return -1;
            }
        }
        unsigned int high_duration = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (!running) return -1;
            delay_us(1);
            high_duration++;
            if (high_duration >= TIMEOUT_US) {
                fprintf(stderr, "Error: Timeout waiting for bit %d end.\n", i);
                return -1;
            }
        }
        data[i / 8] <<= 1;
        if (high_duration > 50) {
            data[i / 8] |= 1;
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Error: Checksum mismatch.\n");
        return -1;
    }

    *humidity = data[0];
    *temperature = data[2];
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int humidity, temperature;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (read_dht11(line, &humidity, &temperature) == 0) {
        printf("Humidity: %d%%, Temperature: %dC\n", humidity, temperature);
        ret = EXIT_SUCCESS;
    } else {
        fprintf(stderr, "Error: Failed to read DHT11 data.\n");
    }

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

