#include <unistd.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int is_valid(int value) {
    return (value == 0 || value == 1);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_2)");
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("gpiod_chip_get_line(GPIO_3)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio2-output", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line3, "gpio3-output", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_3)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val2 = (i % 2 == 0) ? 1 : 0;
        int val3 = (i % 2 == 0) ? 0 : 1;

        if (!is_valid(val2) || !is_valid(val3)) {
            fprintf(stderr, "Invalid value: GPIO_2=%d, GPIO_3=%d\n", val2, val3);
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
