#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 150000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int duty = 0; duty <= PWM_RANGE && running; duty++) {
            if (set_pwm(PWM_PIN_1, duty) != 0) goto cleanup;
            if (set_pwm(PWM_PIN_2, duty) != 0) goto cleanup;
            if (set_pwm(PWM_PIN_3, duty) != 0) goto cleanup;
            printf("PWM1=%3d PWM2=%3d PWM3=%3d\n", duty, duty, duty);
            fflush(stdout);
            usleep(LOOP_DELAY_US);
        }
        for (int duty = PWM_RANGE; duty >= 0 && running; duty--) {
            if (set_pwm(PWM_PIN_1, duty) != 0) goto cleanup;
            if (set_pwm(PWM_PIN_2, duty) != 0) goto cleanup;
            if (set_pwm(PWM_PIN_3, duty) != 0) goto cleanup;
            printf("PWM1=%3d PWM2=%3d PWM3=%3d\n", duty, duty, duty);
            fflush(stdout);
            usleep(LOOP_DELAY_US);
        }
    }

cleanup:
    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

