#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define CYCLE_COUNT 3
#define CYCLE_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    for (int i = 0; i < CYCLE_COUNT && running; i++) {
        int value = (i % 2 == 0) ? 1 : 0;

        if (gpiod_line_set_value(line, value) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE_OFFSET, value);
        fflush(stdout);

        if (i < CYCLE_COUNT - 1) {
            for (int s = 0; s < CYCLE_DELAY_SEC && running; s++) {
                sleep(1);
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

