#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 12
#define PWM_PIN_3 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    while (running) {
        gpioPWM(PWM_PIN_1, 100);
        gpioPWM(PWM_PIN_2, 50);
        gpioPWM(PWM_PIN_3, 0);
        printf("PWM1: 100, PWM2: 50, PWM3: 0\n");
        fflush(stdout);
        gpioDelay(1000000);

        if (!running) break;

        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 100);
        gpioPWM(PWM_PIN_3, 50);
        printf("PWM1: 0, PWM2: 100, PWM3: 50\n");
        fflush(stdout);
        gpioDelay(1000000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

