#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioPWM(PWM_PIN_1, 500) != 0 ||
            gpioPWM(PWM_PIN_2, 300) != 0 ||
            gpioPWM(PWM_PIN_3, 700) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        printf("PWM1: 500, PWM2: 300, PWM3: 700\n");
        fflush(stdout);
        sleep(5);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <dirent.h>
#include <fcntl.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define MAX_DEVICES 3
#define READ_INTERVAL_SEC 5
#define CONVERSION_WAIT_US 750000
#define INVALID_TEMP -1000.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_temperature(const char *device_id, float *out_temp) {
    char path[256];
    int fd;
    char buffer[32];
    ssize_t n;
    long raw;
    float temp;

    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_DEVICES_DIR, device_id);

    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    n = read(fd, buffer, sizeof(buffer) - 1);
    if (n < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buffer[n] = '\0';
    close(fd);

    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "Invalid CRC for device %s\n", device_id);
        return -1;
    }

    char *t = strstr(buffer, "t=");
    if (t == NULL) {
        fprintf(stderr, "Temperature data not found for device %s\n", device_id);
        return -1;
    }

    raw = strtol(t + 2, NULL, 10);
    temp = (float)raw / 1000.0f;

    if (temp < -55.0f || temp > 125.0f) {
        fprintf(stderr, "Temperature out of range for device %s: %.2f\n", device_id, temp);
        return -1;
    }

    *out_temp = temp;
    return 0;
}

int main(void) {
    DIR *dir;
    struct dirent *ent;
    char device_ids[MAX_DEVICES][256];
    int num_devices = 0;
    int i;
    float temperature;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEVICES_DIR, strerror(errno));
        return EXIT_FAILURE;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            if (num_devices < MAX_DEVICES) {
                strncpy(device_ids[num_devices], ent->d_name, sizeof(device_ids[num_devices]) - 1);
                device_ids[num_devices][sizeof(device_ids[num_devices]) - 1] = '\0';
                num_devices++;
            } else {
                fprintf(stderr, "Warning: More than %d DS18B20 devices found. Only using the first %d.\n",
                        MAX_DEVICES, MAX_DEVICES);
                break;
            }
        }
    }
    closedir(dir);

    if (num_devices == 0) {
        fprintf(stderr, "No DS18B20 devices found. Check wiring and that w1-gpio and w1-therm are loaded.\n");
        return EXIT_FAILURE;
    }

    printf("Found %d DS18B20 device(s).\n", num_devices);

    while (g_running) {
        for (i = 0; i < num_devices; i++) {
            if (read_temperature(device_ids[i], &temperature) == 0) {
                printf("Device %s: %.2f C\n", device_ids[i], temperature);
            } else {
                fprintf(stderr, "Failed to read temperature from device %s\n", device_ids[i]);
            }
        }
        sleep(READ_INTERVAL_SEC);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_HUMIDITY_HOLD 0xE5
#define MEASURE_TEMPERATURE_HOLD 0xE3
#define SOFT_RESET 0xFE
#define RESET_DELAY_US 15000
#define MEASURE_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_reset(int fd) {
    if (i2c_write(fd, SOFT_RESET) < 0) return -1;
    usleep(RESET_DELAY_US);
    return 0;
}

static int htu21d_measure(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write(fd, cmd) < 0) return -1;
    usleep(MEASURE_DELAY_US);
    uint8_t buf[3];
    if (i2c_read(fd, buf, 3) < 0) return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    *raw &= 0xFFFC;
    return 0;
}

static float htu21d_convert_humidity(uint16_t raw) {
    return -6.0f + 125.0f * (float)raw / 65536.0f;
}

static float htu21d_convert_temperature(uint16_t raw) {
    return -46.85f + 175.72f * (float)raw / 65536.0f;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (htu21d_reset(fd) < 0) {
        fprintf(stderr, "HTU21D reset failed (device may be absent)\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t raw_humidity, raw_temperature;

        if (htu21d_measure(fd, MEASURE_HUMIDITY_HOLD, &raw_humidity) < 0) {
            fprintf(stderr, "Humidity measurement failed\n");
            break;
        }
        if (htu21d_measure(fd, MEASURE_TEMPERATURE_HOLD, &raw_temperature) < 0) {
            fprintf(stderr, "Temperature measurement failed\n");
            break;
        }

        float humidity = htu21d_convert_humidity(raw_humidity);
        float temperature = htu21d_convert_temperature(raw_temperature);

        if (humidity < 0.0f || humidity > 100.0f) {
            fprintf(stderr, "Humidity out of range: %.2f%%\n", humidity);
            break;
        }
        if (temperature < -40.0f || temperature > 125.0f) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
            break;
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        fflush(stdout);

        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

