#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 17
#define CONSUMER "dht22"
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != target) {
        if (elapsed >= timeout_us) return -1;
        usleep(1);
        elapsed++;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, CONSUMER, 1) < 0) return -1;
    usleep(1000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    if (wait_for_level(line, 0, 1000) < 0) return -1;
    if (wait_for_level(line, 1, 1000) < 0) return -1;
    if (wait_for_level(line, 0, 1000) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, 1000) < 0) return -1;
        int j;
        for (j = 0; j < 100; j++) {
            if (gpiod_line_get_value(line) == 0) break;
            usleep(1);
        }
        if (j >= 100) return -1;
        data[i / 8] <<= 1;
        if (j > 50) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *hum = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int retries;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_dht22(line, &temperature, &humidity) == 0) {
                success = 1;
                break;
            }
            retries++;
            usleep(2000000);
        }

        if (success) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: Failed to read DHT22 after %d retries.\n", MAX_RETRIES);
            gpiod_chip_close(chip);
            return 1;
        }

        for (int i = 0; i < 20 && running; i++) {
            usleep(100000);
        }
    }

    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty1 = 0, duty2 = 0, duty3 = 0;
    int step = 10;

    while (running) {
        if (gpioPWM(PWM_PIN_1, duty1) != 0 ||
            gpioPWM(PWM_PIN_2, duty2) != 0 ||
            gpioPWM(PWM_PIN_3, duty3) != 0) {
            fprintf(stderr, "PWM write failed\n");
            break;
        }
        printf("PWM1: %d, PWM2: %d, PWM3: %d\n", duty1, duty2, duty3);
        fflush(stdout);

        duty1 += step;
        duty2 += step;
        duty3 += step;

        if (duty1 >= PWM_RANGE) duty1 = 0;
        if (duty2 >= PWM_RANGE) duty2 = 0;
        if (duty3 >= PWM_RANGE) duty3 = 0;

        gpioDelay(DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

