#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A
#define TCS34725_POWERON 0x03
#define TCS34725_INTEG_2_4MS 0xFF

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        goto cleanup;
    }

    uint16_t id = 0;
    if (i2c_read16(fd, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "TCS34725 not detected (ID read failed)\n");
        goto cleanup;
    }
    if ((id & 0xFF) != 0x44) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x44)\n", id & 0xFF);
        goto cleanup;
    }

    if (i2c_write(fd, TCS34725_ENABLE, TCS34725_POWERON) < 0) goto cleanup;
    if (i2c_write(fd, TCS34725_ATIME, TCS34725_INTEG_2_4MS) < 0) goto cleanup;

    while (running) {
        uint16_t c, r, g, b;
        if (i2c_read16(fd, TCS34725_CDATA, &c) < 0) break;
        if (i2c_read16(fd, TCS34725_RDATA, &r) < 0) break;
        if (i2c_read16(fd, TCS34725_GDATA, &g) < 0) break;
        if (i2c_read16(fd, TCS34725_BDATA, &b) < 0) break;
        printf("C: %u, R: %u, G: %u, B: %u\n", c, r, g, b);
        fflush(stdout);
        usleep(200000);
    }

    ret = 0;

cleanup:
    if (fd >= 0) {
        i2c_write(fd, TCS34725_ENABLE, 0x00);
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_21 21
#define GPIO_22 22
#define CONSUMER "digital-output"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {GPIO_18, GPIO_21, GPIO_22};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set line %d high\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO %d set HIGH\n", pins[i]);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define OUTPUT_FILE "captured_image.yuv"

static volatile sig_atomic_t stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR && !stop);
    return r;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    unsigned char *buffer = NULL;
    size_t buffer_size = (size_t)IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUV420;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUV420) {
        fprintf(stderr, "Device does not support YUV420 format\n");
        goto cleanup;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        goto streamoff;
    }

    fp = fopen(OUTPUT_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        goto streamoff;
    }

    if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        fprintf(stderr, "Error writing to output file: %s\n", strerror(errno));
        fclose(fp);
        fp = NULL;
        goto streamoff;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing output file: %s\n", strerror(errno));
        fp = NULL;
        goto streamoff;
    }
    fp = NULL;

    printf("Image captured and saved to %s\n", OUTPUT_FILE);
    ret = EXIT_SUCCESS;

streamoff:
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (buffer != NULL && buffer != MAP_FAILED) {
        munmap(buffer, buffer_size);
    }
    if (fd != -1) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_22 22
#define GPIO_27 27
#define CONSUMER "blink"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line22 = NULL, *line27 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line22 = gpiod_chip_get_line(chip, GPIO_22);
    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line22 || !line27) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line22, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output GPIO 22");
        goto cleanup;
    }
    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output GPIO 27");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line22, 1) < 0) {
            perror("gpiod_line_set_value GPIO 22");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 1) < 0) {
            perror("gpiod_line_set_value GPIO 27");
            goto cleanup;
        }
        printf("GPIO 22: HIGH, GPIO 27: HIGH\n");
        fflush(stdout);
        usleep(10000);

        if (gpiod_line_set_value(line22, 0) < 0) {
            perror("gpiod_line_set_value GPIO 22");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 0) < 0) {
            perror("gpiod_line_set_value GPIO 27");
            goto cleanup;
        }
        printf("GPIO 22: LOW, GPIO 27: LOW\n");
        fflush(stdout);
        usleep(10000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line22) gpiod_line_release(line22);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define SSD1306_PAGES (SSD1306_HEIGHT / 8)

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int ssd1306_command(uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write command");
        return -1;
    }
    return 0;
}

int ssd1306_init() {
    if (ssd1306_command(0xAE) < 0) return -1; // Display off
    if (ssd1306_command(0xD5) < 0) return -1; // Set display clock divide ratio/oscillator frequency
    if (ssd1306_command(0x80) < 0) return -1; // Suggested ratio
    if (ssd1306_command(0xA8) < 0) return -1; // Set multiplex ratio
    if (ssd1306_command(0x3F) < 0) return -1; // 64 lines
    if (ssd1306_command(0xD3) < 0) return -1; // Set display offset
    if (ssd1306_command(0x00) < 0) return -1; // No offset
    if (ssd1306_command(0x40) < 0) return -1; // Set start line address
    if (ssd1306_command(0x8D) < 0) return -1; // Charge pump
    if (ssd1306_command(0x14) < 0) return -1; // Enable
    if (ssd1306_command(0x20) < 0) return -1; // Set memory addressing mode
    if (ssd1306_command(0x00) < 0) return -1; // Horizontal addressing mode
    if (ssd1306_command(0xA1) < 0) return -1; // Segment remap
    if (ssd1306_command(0xC8) < 0) return -1; // COM scan direction
    if (ssd1306_command(0xDA) < 0) return -1; // Set COM pins hardware configuration
    if (ssd1306_command(0x12) < 0) return -1; // Alternative pin configuration
    if (ssd1306_command(0x81) < 0) return -1; // Set contrast
    if (ssd1306_command(0xCF) < 0) return -1; // Contrast value
    if (ssd1306_command(0xD9) < 0) return -1; // Set pre-charge period
    if (ssd1306_command(0xF1) < 0) return -1; // Phase 1: 15 DCLK, Phase 2: 1 DCLK
    if (ssd1306_command(0xDB) < 0) return -1; // Set VCOMH deselect level
    if (ssd1306_command(0x40) < 0) return -1; // ~0.77 x VCC
    if (ssd1306_command(0xA4) < 0) return -1; // Resume to RAM content display
    if (ssd1306_command(0xA6) < 0) return -1; // Normal display (not inverted)
    if (ssd1306_command(0xAF) < 0) return -1; // Display on
    return 0;
}

int ssd1306_display_on() {
    return ssd1306_command(0xAF);
}

int ssd1306_display_off() {
    return ssd1306_command(0xAE);
}

int ssd1306_clear_display() {
    if (ssd1306_command(0x21) < 0) return -1; // Set column address range
    if (ssd1306_command(0x00) < 0) return -1; // Start at column 0
    if (ssd1306_command(0x7F) < 0) return -1; // End at column 127
    if (ssd1306_command(0x22) < 0) return -1; // Set page address range
    if (ssd1306_command(0x00) < 0) return -1; // Start at page 0
    if (ssd1306_command(0x07) < 0) return -1; // End at page 7

    uint8_t buf[128];
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 128; j++) {
            buf[j] = 0x00;
        }
        if (write(i2c_fd, buf, 128) != 128) {
            perror("Failed to clear display");
            return -1;
        }
    }
    return 0;
}

int ssd1306_set_cursor(int page, int column) {
    if (ssd1306_command(0x21) < 0) return -1; // Set column address range
    if (ssd1306_command(column) < 0) return -1;
    if (ssd1306_command(0x7F) < 0) return -1;
    if (ssd1306_command(0x22) < 0) return -1; // Set page address range
    if (ssd1306_command(page) < 0) return -1;
    if (ssd1306_command(0x07) < 0) return -1;
    return 0;
}

int ssd1306_write_data(const uint8_t *data, size_t len) {
    uint8_t buf[129];
    buf[0] = 0x40; // Data mode
    for (size_t i = 0; i < len; i++) {
        buf[i + 1] = data[i];
    }
    if (write(i2c_fd, buf, len + 1) != (ssize_t)(len + 1)) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

void cleanup() {
    if (i2c_fd >= 0) {
        ssd1306_display_off();
        ssd1306_clear_display();
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (ssd1306_init() < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        cleanup();
        return 1;
    }

    ssd1306_display_on();

    struct timespec ts = {0, 100000000}; // 0.1 seconds

    while (running) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        ssd1306_clear_display();

        ssd1306_set_cursor(0, 0);
        ssd1306_write_data((uint8_t *)"Time: ", 6);
        ssd1306_write_data((uint8_t *)buffer, strlen(buffer));

        ssd1306_set_cursor(1, 0);
        ssd1306_write_data((uint8_t *)"Date: ", 6);
        ssd1306_write_data((uint8_t *)buffer, strlen(buffer));

        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        long remaining_ns = ts.tv_nsec - elapsed_ns;
        if (remaining_ns < 0) {
            remaining_ns += 1000000000L;
        }
        struct timespec sleep_ts = {0, remaining_ns};
        nanosleep(&sleep_ts, NULL);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5
#define CONSUMER "gpio-toggle"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {GPIO_2, GPIO_3, GPIO_5};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read line %d\n", pins[i]);
                goto cleanup;
            }
            int new_val = val ? 0 : 1;
            if (gpiod_line_set_value(lines[i], new_val) < 0) {
                fprintf(stderr, "Failed to set line %d\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %d: %d\n", pins[i], new_val);
        }
        fflush(stdout);
        sleep(5);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int duty = (i % 2 == 0) ? 128 : 255;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "gpioPWM failed on pin %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Pin %d PWM duty: %d\n", pins[i], duty);
        }
        fflush(stdout);
        time_sleep(1.0);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define STATE_PIN   24
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  30000  /* 30 ms timeout for echo (max range ~5 m) */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static long measure_echo_us(struct gpiod_line *echo)
{
    struct timespec ts_start, ts_end;
    long elapsed;

    /* Wait for echo rising edge */
    if (gpiod_line_get_value(echo) != 0)
        return -1;
    while (gpiod_line_get_value(echo) != 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0)
            return -1;
        if (!running)
            return -1;
    }

    /* Wait for echo falling edge with timeout */
    while (gpiod_line_get_value(echo) != 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0)
            return -1;
        elapsed = (ts_end.tv_sec - ts_start.tv_sec) * 1000000L
                + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed > TIMEOUT_US)
            return -1;
        if (!running)
            return -1;
    }

    return elapsed;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *state = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig  = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo  = gpiod_chip_get_line(chip, ECHO_PIN);
    state = gpiod_chip_get_line(chip, STATE_PIN);
    if (!trig || !echo || !state) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(state, "hcsr04-state", 0) < 0) {
        perror("gpiod_line_request_output (state)");
        goto cleanup;
    }

    while (running) {
        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value (trig high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trig low)");
            break;
        }

        long dur = measure_echo_us(echo);
        if (dur < 0) {
            /* Timeout or signal: report 0 distance */
            dur = 0;
        }

        /* State = 1 if object within 40 cm (~4000 us round trip) */
        int st = (dur > 0 && dur < 4000) ? 1 : 0;
        if (gpiod_line_set_value(state, st) < 0) {
            perror("gpiod_line_set_value (state)");
            break;
        }

        printf("Distance: %ld us, State: %d\n", dur, st);
        fflush(stdout);

        usleep(200000);  /* 0.2 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)  gpiod_line_release(trig);
    if (echo)  gpiod_line_release(echo);
    if (state) gpiod_line_release(state);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define PIXEL_PIN 18
#define DELAY_US 10000  /* 10 ms = 0.01 s */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pixel(int pin, int red, int green, int blue) {
    /*
     * WS2812 requires a specific timing protocol.  pigpio's bit-banged
     * output is sufficient for a single strip; for multiple strips or
     * higher performance, use the hardware PWM peripheral.
     */
    if (gpioWrite(pin, 1) < 0) return -1;
    gpioDelay(DELAY_US);
    if (gpioWrite(pin, 0) < 0) return -1;
    gpioDelay(DELAY_US);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIXEL_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PIXEL_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (set_pixel(PIXEL_PIN, 255, 0, 0) < 0) {
            fprintf(stderr, "Failed to write to GPIO %d\n", PIXEL_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_pixel(PIXEL_PIN, 0, 255, 0) < 0) {
            fprintf(stderr, "Failed to write to GPIO %d\n", PIXEL_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_pixel(PIXEL_PIN, 0, 0, 255) < 0) {
            fprintf(stderr, "Failed to write to GPIO %d\n", PIXEL_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

