#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define HD44780_ADDR 0x27
#define HD44780_CHR 1
#define HD44780_CMD 0
#define HD44780_LINE1 0x80
#define HD44780_LINE2 0xC0
#define HD44780_DISPLAY_ON 0x0C
#define HD44780_CLEAR 0x01
#define HD44780_ENTRY_MODE 0x06

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void delay_ms(int ms) {
    usleep(ms * 1000);
}

static void hd44780_write(int fd, uint8_t bits, uint8_t mode) {
    uint8_t high = mode | (bits & 0xF0) | 0x08;
    uint8_t low = mode | ((bits << 4) & 0xF0) | 0x08;
    uint8_t buf[4] = {high, high | 0x04, low, low | 0x04};
    if (write(fd, buf, 4) != 4) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
}

static void hd44780_init(int fd) {
    delay_ms(50);
    hd44780_write(fd, 0x30, HD44780_CMD);
    delay_ms(5);
    hd44780_write(fd, 0x30, HD44780_CMD);
    delay_ms(1);
    hd44780_write(fd, 0x30, HD44780_CMD);
    delay_ms(1);
    hd44780_write(fd, 0x20, HD44780_CMD);
    delay_ms(1);
    hd44780_write(fd, HD44780_DISPLAY_ON, HD44780_CMD);
    delay_ms(1);
    hd44780_write(fd, HD44780_CLEAR, HD44780_CMD);
    delay_ms(2);
    hd44780_write(fd, HD44780_ENTRY_MODE, HD44780_CMD);
    delay_ms(1);
}

static void hd44780_clear(int fd) {
    hd44780_write(fd, HD44780_CLEAR, HD44780_CMD);
    delay_ms(2);
}

static void hd44780_set_cursor(int fd, int line) {
    hd44780_write(fd, line, HD44780_CMD);
    delay_ms(1);
}

static void hd44780_print(int fd, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        hd44780_write(fd, (uint8_t)str[i], HD44780_CHR);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    hd44780_init(fd);

    while (running) {
        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        hd44780_clear(fd);
        hd44780_set_cursor(fd, HD44780_LINE1);
        hd44780_print(fd, "Time: ");
        hd44780_print(fd, buffer);

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        hd44780_set_cursor(fd, HD44780_LINE2);
        hd44780_print(fd, "Date: ");
        hd44780_print(fd, buffer);

        for (int i = 0; i < 10 && running; i++) {
            delay_ms(1000);
        }
    }

    hd44780_clear(fd);
    hd44780_set_cursor(fd, HD44780_LINE1);
    hd44780_print(fd, "Exiting...");
    delay_ms(1000);
    hd44780_clear(fd);

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int mpu6050_init(int fd) {
    uint8_t whoami;
    if (i2c_read_reg8(fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x68)\n", whoami);
        return -1;
    }
    if (i2c_read_reg8(fd, PWR_MGMT_1, &whoami) < 0) {
        fprintf(stderr, "Error reading PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg8(fd, PWR_MGMT_1, &whoami) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        goto cleanup;
    }

    for (int i = 0; i < 100 && running; i++) {
        int16_t ax, ay, az, gx, gy, gz;

        if (i2c_read_reg16(fd, ACCEL_XOUT_H, &ax) < 0 ||
            i2c_read_reg16(fd, ACCEL_YOUT_H, &ay) < 0 ||
            i2c_read_reg16(fd, ACCEL_ZOUT_H, &az) < 0 ||
            i2c_read_reg16(fd, GYRO_XOUT_H,  &gx) < 0 ||
            i2c_read_reg16(fd, GYRO_YOUT_H,  &gy) < 0 ||
            i2c_read_reg16(fd, GYRO_ZOUT_H,  &gz) < 0) {
            fprintf(stderr, "Error reading sensor data at iteration %d: %s\n", i, strerror(errno));
            goto cleanup;
        }

        printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);
        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_14 14
#define GPIO_15 15
#define CONSUMER "blink"
#define INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL, *line15 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line14 = gpiod_chip_get_line(chip, GPIO_14);
    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line14 || !line15) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line14, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (GPIO 14)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line15, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (GPIO 15)");
        goto cleanup;
    }

    while (running) {
        int v14 = gpiod_line_get_value(line14);
        int v15 = gpiod_line_get_value(line15);
        if (v14 < 0 || v15 < 0) {
            fprintf(stderr, "gpiod_line_get_value failed (v14=%d v15=%d)\n", v14, v15);
            goto cleanup;
        }

        int n14 = v14 ? 0 : 1;
        int n15 = v15 ? 0 : 1;

        if (gpiod_line_set_value(line14, n14) < 0) {
            perror("gpiod_line_set_value (GPIO 14)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line15, n15) < 0) {
            perror("gpiod_line_set_value (GPIO 15)");
            goto cleanup;
        }

        printf("GPIO 14: %d, GPIO 15: %d\n", n14, n15);
        fflush(stdout);

        for (int i = 0; i < INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line14) gpiod_line_release(line14);
    if (line15) gpiod_line_release(line15);
    if (chip)   gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_pub"
#define MQTT_TOPIC "sensor/data"
#define SENSOR_PIN 4
#define READ_INTERVAL_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static MQTTClient client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return value;
}

static int validate_sensor_data(int data) {
    if (data < 0 || data > 100) {
        fprintf(stderr, "Invalid sensor data: %d\n", data);
        return -1;
    }
    return 0;
}

static int publish_sensor_data(int data) {
    char payload[64];
    int rc;

    snprintf(payload, sizeof(payload), "%d", data);

    rc = MQTTClient_publishMessage(client, MQTT_TOPIC, payload, strlen(payload),
                                   MQTTCLIENT_QOS0, MQTTCLIENT_RETAIN_NONE);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (client != NULL) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
    }
    gpioTerminate();
}

int main(void) {
    int rc;
    int sensor_data;
    int retries;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);

    rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                           MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    printf("MQTT client connected. Publishing sensor data to %s\n", MQTT_TOPIC);

    while (running) {
        retries = 0;
        sensor_data = -1;

        while (retries < MAX_RETRIES && running) {
            sensor_data = read_sensor(SENSOR_PIN);
            if (sensor_data != -1) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(100000);
            }
        }

        if (sensor_data == -1) {
            fprintf(stderr, "Failed to read sensor data after %d retries. Exiting.\n", MAX_RETRIES);
            break;
        }

        if (validate_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Invalid sensor data received. Skipping.\n");
            continue;
        }

        if (publish_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to publish sensor data. Exiting.\n");
            break;
        }

        usleep(READ_INTERVAL_US);
    }

    cleanup();
    return 0;
}

