#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  200000  /* 200 ms timeout for echo */
#define MIN_DIST_CM 2.0f
#define MAX_DIST_CM 400.0f
#define SAMPLE_PERIOD_US 100000  /* 0.1 s */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm. Returns true on success, false on timeout or
 * out-of-range.
 */
static bool measure_distance(struct gpiod_line *trigger,
                             struct gpiod_line *echo,
                             float *distance)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trigger, 0) < 0)
        return false;
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trigger, 1) < 0)
        return false;
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0)
        return false;

    /* Wait for echo rising edge (timeout) */
    int elapsed = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (elapsed >= TIMEOUT_US)
            return false;
        usleep(1);
        elapsed++;
    }

    /* Measure echo pulse width */
    int pulse_us = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (pulse_us >= TIMEOUT_US)
            return false;
        usleep(1);
        pulse_us++;
    }

    /* speed of sound 343 m/s => 0.0343 cm/us; round trip => /2 */
    float dist = (float)pulse_us * 0.0343f / 2.0f;

    if (dist < MIN_DIST_CM || dist > MAX_DIST_CM)
        return false;

    *distance = dist;
    return true;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    while (running) {
        float distance;
        if (measure_distance(trigger, echo, &distance)) {
            printf("Distance: %.2f cm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Measurement failed (timeout or out of range)\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger)
        gpiod_line_release(trigger);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

