#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_pub"
#define MQTT_TOPIC "sensor/data"
#define SENSOR_GPIO 4
#define QOS 1
#define TIMEOUT_SEC 10

static volatile sig_atomic_t running = 1;
static MQTTClient client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1;
    }
    return value;
}

static int publish_sensor_data(int sensor_value, const char *topic) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = QOS;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    int rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    int sensor_value = read_sensor(SENSOR_GPIO);
    if (sensor_value < 0) {
        fprintf(stderr, "Sensor read failed; exiting\n");
        MQTTClient_disconnect(client, TIMEOUT_SEC);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    if (publish_sensor_data(sensor_value, MQTT_TOPIC) != 0) {
        fprintf(stderr, "Failed to publish sensor data\n");
        MQTTClient_disconnect(client, TIMEOUT_SEC);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    printf("Sensor value %d published to %s\n", sensor_value, MQTT_TOPIC);

    MQTTClient_disconnect(client, TIMEOUT_SEC);
    MQTTClient_destroy(&client);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    int duty = 0;
    int step = 10;
    int direction = 1;

    while (running) {
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", PWM_PIN);
            break;
        }
        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);

        duty += step * direction;
        if (duty >= PWM_RANGE) {
            duty = PWM_RANGE;
            direction = -1;
        } else if (duty <= 0) {
            duty = 0;
            direction = 1;
        }

        for (int i = 0; i < 50 && running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  30000   /* 30 ms timeout for echo (max range ~5 m) */
#define LOOP_DELAY  200000  /* 200 ms between readings */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(long long us)
{
    struct timespec ts;
    ts.tv_sec  = (time_t)(us / 1000000LL);
    ts.tv_nsec = (long)((us % 1000000LL) * 1000LL);
    nanosleep(&ts, NULL);
}

/*
 * Measure distance in centimetres.
 * Returns -1.0 on timeout or error.
 */
static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    long long t0, t1;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0)
        return -1.0f;
    sleep_us(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0)
        return -1.0f;
    sleep_us(10);
    if (gpiod_line_set_value(trig, 0) < 0)
        return -1.0f;

    /* Wait for echo rising edge (timeout) */
    t0 = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() - t0 > TIMEOUT_US)
            return -1.0f;
    }
    t0 = now_us();

    /* Wait for echo falling edge (timeout) */
    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() - t0 > TIMEOUT_US)
            return -1.0f;
    }
    t1 = now_us();

    long long pulse_us = t1 - t0;
    /* speed of sound 343 m/s => 0.0343 cm/us; round trip => /2 */
    return (float)pulse_us * 0.0343f / 2.0f;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    while (running) {
        float dist = measure_distance(trig, echo);
        if (dist < 0.0f) {
            printf("Error: sensor read failed\n");
        } else {
            printf("Distance: %.2f cm\n", dist);
        }
        fflush(stdout);
        sleep_us(LOOP_DELAY);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_4, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioPWM(PWM_PIN_1, 250) != 0 ||
            gpioPWM(PWM_PIN_2, 500) != 0 ||
            gpioPWM(PWM_PIN_3, 750) != 0 ||
            gpioPWM(PWM_PIN_4, 1000) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        printf("PWM1: 250, PWM2: 500, PWM3: 750, PWM4: 1000\n");
        fflush(stdout);
        gpioDelay(100000); /* 0.1 seconds in microseconds */
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_pub"
#define MQTT_TOPIC "sensor/data"
#define SENSOR_PIN 4
#define TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    return val;
}

static int validate_sensor_data(int data) {
    if (data < 0 || data > 100) {
        fprintf(stderr, "Invalid sensor data: %d\n", data);
        return -1;
    }
    return 0;
}

static int publish_sensor_data(MQTTClient client, const char *topic, int data) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", data);

    MQTTClient_message message = MQTTClient_message_initializer;
    message.payload = payload;
    message.payloadlen = (int)strlen(payload);
    message.qos = 0;
    message.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, topic, &message, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);

    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;
    conn_opts.timeout = TIMEOUT_MS;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    int sensor_data = read_sensor(SENSOR_PIN);
    if (sensor_data < 0) {
        fprintf(stderr, "Sensor read failed; exiting.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    if (validate_sensor_data(sensor_data) != 0) {
        fprintf(stderr, "Sensor data validation failed; exiting.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    if (publish_sensor_data(client, MQTT_TOPIC, sensor_data) != 0) {
        fprintf(stderr, "Failed to publish sensor data; exiting.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    printf("Sensor data published: %d\n", sensor_data);

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_ads1115"
#define MQTT_TOPIC "sensor/ads1115"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define NUM_READINGS 10

static volatile sig_atomic_t running = 1;
static MQTTClient client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ads1115(int handle, int16_t *value) {
    char config[2];
    config[0] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) & 0xFF;

    if (i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, config, 2) < 0) {
        return -1;
    }

    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) < 0) {
        return -1;
    }

    *value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static int publish_reading(int16_t value) {
    char payload[16];
    int len = snprintf(payload, sizeof(payload), "%d", value);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        return -1;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = len;
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    if (MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token) != MQTTCLIENT_SUCCESS) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                          MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    int rc = 0;
    for (int i = 0; i < NUM_READINGS && running; i++) {
        int16_t value;
        if (read_ads1115(handle, &value) == 0) {
            if (publish_reading(value) != 0) {
                fprintf(stderr, "Failed to publish reading %d\n", i);
                rc = 1;
                break;
            }
        } else {
            fprintf(stderr, "Failed to read ADS1115 at iteration %d\n", i);
            rc = 1;
            break;
        }
        gpioDelay(100000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(handle);
    gpioTerminate();

    return rc;
}

#include <stdio.h>
