        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (GPIO 18)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 18)");
            goto cleanup;
        }
        printf("GPIO 17: HIGH, GPIO 18: HIGH\n");
        fflush(stdout);
        usleep(50000);

        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 18)");
            goto cleanup;
        }
        printf("GPIO 17: LOW, GPIO 18: LOW\n");
        fflush(stdout);
        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

