#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>

#define BAUD_RATE B115200
#define SERIAL_PORT "/dev/ttyS0"
#define READ_BUF_SIZE 256

static volatile sig_atomic_t running = 1;
static int serial_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_serial_port(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

int read_serial_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    } else if (bytes_read == -1) {
        if (errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("Error reading from serial port");
        }
    }
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    serial_fd = init_serial_port(SERIAL_PORT, BAUD_RATE);
    if (serial_fd == -1) {
        return 1;
    }

    char read_buffer[READ_BUF_SIZE];
    int bytes_read;

    while (running) {
        bytes_read = read_serial_data(serial_fd, read_buffer, sizeof(read_buffer));
        if (bytes_read > 0) {
            printf("Received: %s", read_buffer);
        }
        usleep(100000);
    }

    if (serial_fd != -1) {
        close(serial_fd);
    }
    printf("\nSerial port closed. Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int mpu6050_init(int fd) {
    uint8_t whoami;
    if (i2c_read_reg8(fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x68)\n", whoami);
        return -1;
    }
    if (i2c_read_reg8(fd, PWR_MGMT_1, &whoami) < 0) {
        fprintf(stderr, "Error reading PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg8(fd, PWR_MGMT_1, &whoami) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int16_t ax, ay, az, gx, gy, gz;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_read_reg16(fd, ACCEL_XOUT_H, &ax) < 0 ||
            i2c_read_reg16(fd, ACCEL_YOUT_H, &ay) < 0 ||
            i2c_read_reg16(fd, ACCEL_ZOUT_H, &az) < 0 ||
            i2c_read_reg16(fd, GYRO_XOUT_H, &gx) < 0 ||
            i2c_read_reg16(fd, GYRO_YOUT_H, &gy) < 0 ||
            i2c_read_reg16(fd, GYRO_ZOUT_H, &gz) < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            break;
        }
        printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);
        usleep(100000);
    }

    if (fd >= 0) close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_ID 0xD0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x58 && id != 0x60) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x58 or 0x60)\n", id);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;

    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    *temperature = (float)raw_temperature / 100.0f;
    *pressure = (float)raw_pressure / 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(fd);
        return 1;
    }

    while (running) {
        float temperature, pressure;
        if (bmp280_read(fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading BMP280 data: %s\n", strerror(errno));
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 128) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM duty cycle set to 128/255 on GPIO %d\n", PWM_PIN);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped and GPIO released.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_5  5
#define GPIO_6  6
#define GPIO_13 13

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {GPIO_5, GPIO_6, GPIO_13};
    int i;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], "gpio5613", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 3; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
        printf("GPIO %d set HIGH\n", pins[i]);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_pub"
#define MQTT_TOPIC "sensor/data"
#define SENSOR_PIN 4
#define QOS 1

static volatile sig_atomic_t running = 1;
static MQTTClient client;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sensor_data() {
    return gpioRead(SENSOR_PIN);
}

int publish_sensor_data(int sensor_value) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = QOS;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    int sensor_value = read_sensor_data();
    if (publish_sensor_data(sensor_value) != 0) {
        fprintf(stderr, "Failed to publish sensor data\n");
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_PIN_4 23
#define PWM_PIN_5 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM signals applied to GPIO 2, 3, 18, 23, 24\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioPWM(PWM_PIN_1, 255) != 0 ||
            gpioPWM(PWM_PIN_2, 128) != 0 ||
            gpioPWM(PWM_PIN_3, 64) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        printf("PWM 17: 255, PWM 22: 128, PWM 27: 64\n");
        fflush(stdout);
        gpioDelay(DELAY_US);

        if (gpioPWM(PWM_PIN_1, 64) != 0 ||
            gpioPWM(PWM_PIN_2, 128) != 0 ||
            gpioPWM(PWM_PIN_3, 255) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        printf("PWM 17: 64, PWM 22: 128, PWM 27: 255\n");
        fflush(stdout);
        gpioDelay(DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define CAPTURE_INTERVAL 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_image(int fd, const char *filename) {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    void *buffer_start = NULL;
    size_t buffer_length = 0;
    int ret = -1;

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT failed");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF failed");
        return -1;
    }

    buffer_length = buf.length;
    buffer_start = mmap(NULL, buffer_length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF failed");
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF failed");
        goto streamoff;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen failed");
        goto streamoff;
    }

    if (fwrite(buffer_start, 1, buf.bytesused, fp) != buf.bytesused) {
        perror("fwrite failed");
        fclose(fp);
        goto streamoff;
    }

    fclose(fp);
    ret = 0;

streamoff:
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &type);

cleanup:
    if (buffer_start != NULL && buffer_start != MAP_FAILED) {
        munmap(buffer_start, buffer_length);
    }
    return ret;
}

int main(void) {
    int fd = -1;
    char filename[64];
    int image_count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    while (running) {
        snprintf(filename, sizeof(filename), "image_%d.jpg", image_count);
        printf("Capturing image %d...\n", image_count);
        if (capture_image(fd, filename) == 0) {
            printf("Image saved as %s\n", filename);
        } else {
            fprintf(stderr, "Failed to capture image %d\n", image_count);
        }
        image_count++;
        sleep(CAPTURE_INTERVAL);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
