#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>

#define BAUD_RATE B115200
#define READ_BUF_SIZE 256
#define WRITE_BUF_SIZE 256

static volatile sig_atomic_t running = 1;
static int serial_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_serial(const char *device) {
    serial_fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd < 0) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    tcflush(serial_fd, TCIOFLUSH);
    return 0;
}

static int read_serial(char *buffer, size_t max_len) {
    ssize_t bytes_read = read(serial_fd, buffer, max_len - 1);
    if (bytes_read < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        perror("Error reading from serial port");
        return -1;
    }
    if (bytes_read == 0) {
        return 0;
    }
    buffer[bytes_read] = '\0';
    return (int)bytes_read;
}

static int write_serial(const char *data) {
    size_t len = strlen(data);
    ssize_t bytes_written = write(serial_fd, data, len);
    if (bytes_written < 0) {
        perror("Error writing to serial port");
        return -1;
    }
    if ((size_t)bytes_written != len) {
        fprintf(stderr, "Partial write: %zd of %zu bytes\n", bytes_written, len);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <serial_device>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    if (init_serial(argv[1]) != 0) {
        return EXIT_FAILURE;
    }

    char read_buf[READ_BUF_SIZE];
    char write_buf[WRITE_BUF_SIZE];

    while (running) {
        int bytes_read = read_serial(read_buf, sizeof(read_buf));
        if (bytes_read < 0) {
            break;
        }
        if (bytes_read > 0) {
            printf("Received: %s", read_buf);
            fflush(stdout);
        }

        snprintf(write_buf, sizeof(write_buf), "Hello, Serial!\n");
        if (write_serial(write_buf) != 0) {
            break;
        }

        usleep(100000);
    }

    if (serial_fd >= 0) {
        close(serial_fd);
        serial_fd = -1;
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
