#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 128) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d set to 128/255\n", PWM_PIN);
    fflush(stdout);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped and GPIO released\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 27
#define INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "blink", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        int new_val = val ? 0 : 1;
        if (gpiod_line_set_value(line, new_val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE, new_val);
        fflush(stdout);
        sleep(INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 10
#define PWM_PIN_4 11
#define PWM_PIN_5 17

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int duty_cycle = 128; /* 0-255 range */
    for (int i = 0; i < num_pins; i++) {
        if (gpioPWM(pins[i], duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("GPIO %d PWM duty cycle set to %d\n", pins[i], duty_cycle);
    }

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Turn off PWM and release hardware */
    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("PWM output stopped and GPIO released.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or bus error).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    int direction = 1;

    while (running) {
        if (gpioPWM(PWM_PIN_1, duty_cycle) != 0 ||
            gpioPWM(PWM_PIN_2, duty_cycle) != 0 ||
            gpioPWM(PWM_PIN_3, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle.\n");
            break;
        }

        printf("PWM duty cycle: %d\n", duty_cycle);
        fflush(stdout);

        duty_cycle += direction;
        if (duty_cycle >= PWM_RANGE) {
            duty_cycle = PWM_RANGE;
            direction = -1;
        } else if (duty_cycle <= 0) {
            duty_cycle = 0;
            direction = 1;
        }

        gpioDelay(DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_RETRIES 5
#define TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, uint32_t timeout_us) {
    uint32_t start = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        if (start == 0) start = 1;
        usleep(1);
        timeout_us--;
        if (timeout_us == 0) return -1;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (!running) return -1;

        gpiod_line_request_output(line, "dht22", 0);
        usleep(1000);
        gpiod_line_set_value(line, 1);
        usleep(30);
        gpiod_line_set_value(line, 0);
        usleep(20000);
        gpiod_line_set_value(line, 1);
        usleep(30);

        gpiod_line_request_input(line, "dht22");

        if (wait_for_level(line, 0, TIMEOUT_US) < 0) continue;
        if (wait_for_level(line, 1, TIMEOUT_US) < 0) continue;
        if (wait_for_level(line, 0, TIMEOUT_US) < 0) continue;

        for (i = 0; i < 40; i++) {
            if (wait_for_level(line, 1, TIMEOUT_US) < 0) goto retry;
            uint32_t start = 0;
            while (gpiod_line_get_value(line) == 1) {
                if (!running) return -1;
                if (start == 0) start = 1;
                usleep(1);
                TIMEOUT_US--;
                if (TIMEOUT_US == 0) goto retry;
            }
            if (start > 40) {
                data[i / 8] <<= 1;
                if (start > 100) data[i / 8] |= 1;
            }
        }

        if (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
            *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
            *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
            if (data[2] & 0x80) *temp = -*temp;
            return 0;
        }
    retry:
        continue;
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    float temp, hum;
    int rc = read_dht22(line, &temp, &hum);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (rc == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        return 0;
    } else {
        fprintf(stderr, "Failed to read DHT22 after %d retries.\n", MAX_RETRIES);
        return 1;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 4
#define CONSUMER "bcm-output-toggle"

static const unsigned int pins[NUM_PINS] = {17, 23, 24, 25};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS] = {0, 0, 0, 0};
    int rc = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Failed to set line %u\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %u: %d\n", pins[i], values[i]);
        }
        fflush(stdout);
        sleep(10);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MCP3008_CS 8
#define MCP3008_CLK 9
#define MCP3008_DOUT 10
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_mcp3008"
#define MQTT_TOPIC "sensor/mcp3008"
#define NUM_SENSORS 4

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    gpioWrite(MCP3008_CS, 0);
    gpioDelay(10);

    int value = 0;
    gpioWrite(MCP3008_CLK, 0);
    gpioDelay(10);

    // Start bit
    gpioWrite(MCP3008_CLK, 1);
    gpioDelay(10);
    gpioWrite(MCP3008_CLK, 0);
    gpioDelay(10);

    // Single-ended mode
    gpioWrite(MCP3008_CLK, 1);
    gpioDelay(10);
    gpioWrite(MCP3008_CLK, 0);
    gpioDelay(10);

    // Channel selection (3 bits)
    for (int i = 2; i >= 0; i--) {
        if (channel & (1 << i)) {
            gpioWrite(MCP3008_CLK, 1);
        } else {
            gpioWrite(MCP3008_CLK, 0);
        }
        gpioDelay(10);
        gpioWrite(MCP3008_CLK, 0);
        gpioDelay(10);
    }

    // Read 10 bits
    for (int i = 0; i < 10; i++) {
        gpioWrite(MCP3008_CLK, 1);
        gpioDelay(10);
        value = (value << 1) | gpioRead(MCP3008_DOUT);
        gpioWrite(MCP3008_CLK, 0);
        gpioDelay(10);
    }

    gpioWrite(MCP3008_CS, 1);
    return value;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_CLK, PI_OUTPUT);
    gpioSetMode(MCP3008_DOUT, PI_INPUT);
    gpioWrite(MCP3008_CS, 1);

    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    int sensor_values[NUM_SENSORS];
    char payload[256];

    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                continue;
            }
            snprintf(payload, sizeof(payload), "%d", sensor_values[i]);
            MQTTClient_message pubmsg = MQTTClient_message_initializer;
            pubmsg.payload = payload;
            pubmsg.payloadlen = (int)strlen(payload);
            pubmsg.qos = 0;
            pubmsg.retained = 0;

            MQTTClient_deliveryToken token;
            rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
            if (rc != MQTTCLIENT_SUCCESS) {
                fprintf(stderr, "Failed to publish message to topic %s, return code %d\n",
                        MQTT_TOPIC, rc);
            }
        }
        sleep(1);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define OUTPUT_FILE "captured_image.yuv"

static void cleanup(int fd, void *buffer, size_t buffer_size) {
    if (buffer && buffer_size > 0) {
        munmap(buffer, buffer_size);
    }
    if (fd >= 0) {
        close(fd);
    }
}

int main() {
    int fd = -1;
    void *buffer = NULL;
    size_t buffer_size = 0;
    int ret = 1;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUV420;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUV420) {
        fprintf(stderr, "Device does not support YUV420 format\n");
        goto cleanup;
    }

    buffer_size = IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        buffer = NULL;
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        goto streamoff;
    }

    FILE *fp = fopen(OUTPUT_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        goto streamoff;
    }

    if (fwrite(buffer, 1, buffer_size, fp) != buffer_size) {
        fprintf(stderr, "Error writing to output file: %s\n", strerror(errno));
        fclose(fp);
        goto streamoff;
    }

    fclose(fp);
    printf("Image captured and saved to %s\n", OUTPUT_FILE);
    ret = 0;

streamoff:
    ioctl(fd, VIDIOC_STREAMOFF, &type);
cleanup:
    cleanup(fd, buffer, buffer_size);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_PINS 6
static const int pins[NUM_PINS] = {4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
