#define PCF8574_ADDR 0x20
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int pcf8574_write(int fd, uint8_t val) {
    if (write(fd, &val, 1) != 1) {
        perror("write to PCF8574 failed");
        return -1;
    }
    return 0;
}

static int read_sensor(int sensor_id) {
    int value = (int)(sensor_id * 10.0);
    if (value > 100) value = 100;
    if (value < 0) value = 0;
    return value;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus failed");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("ioctl I2C_SLAVE failed");
        goto cleanup;
    }

    while (running) {
        int sensor1 = read_sensor(1);
        int sensor2 = read_sensor(2);
        int sensor3 = read_sensor(3);

        uint8_t output = (uint8_t)(sensor1 | (sensor2 << 4) | (sensor3 << 8));

        if (pcf8574_write(fd, output) != 0) {
            goto cleanup;
        }

        struct timespec ts = {0, 500000000};
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        pcf8574_write(fd, 0x00);
        close(fd);
    }
    return ret;
}

