#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x20
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int pcf8574_write(int fd, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &value, 1) == 1) {
            return 0;
        }
        if (errno == EINTR) {
            continue;
        }
        fprintf(stderr, "I2C write failed (attempt %d): %s\n", attempt + 1, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static void display_number(int fd, int number) {
    uint8_t segments[10] = {
        0x3F, 0x06, 0x5B, 0x4F, 0x66,
        0x6D, 0x7D, 0x07, 0x7F, 0x6F
    };
    if (number < 0 || number > 9) {
        fprintf(stderr, "Invalid number: %d\n", number);
        return;
    }
    if (pcf8574_write(fd, segments[number]) != 0) {
        fprintf(stderr, "Failed to write number %d to display\n", number);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    for (int i = 0; i <= 9 && running; i++) {
        display_number(fd, i);
        usleep(500000);
    }

    if (pcf8574_write(fd, 0x00) != 0) {
        fprintf(stderr, "Failed to clear display on exit\n");
    }

    close(fd);
    return 0;
}

