#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  30000   /* 30 ms timeout for echo (max range ~5 m) */
#define SETTLE_US   10000   /* 10 ms settle time between measurements */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Measure distance in centimetres using the HC-SR04.
 * Returns 0 on success and stores the distance in *out_cm.
 * Returns -1 on timeout or error.
 */
static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo,
                            float *out_cm)
{
    /* Ensure trigger starts LOW */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig, 1)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    uint64_t t0 = 0;
    int val;
    for (;;) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            return -1;
        }
        if (val == 1) {
            t0 = gpiod_line_get_time(echo);
            if (t0 == 0) {
                /* Fallback: use monotonic usleep */
                t0 = (uint64_t)clock() * 1000000 / (uint64_t)CLOCKS_PER_SEC;
            }
            break;
        }
        if (--t0 == 0) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
        usleep(1);
    }

    /* Wait for echo falling edge (timeout) */
    uint64_t t1 = 0;
    for (;;) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            return -1;
        }
        if (val == 0) {
            t1 = gpiod_line_get_time(echo);
            if (t1 == 0) {
                t1 = (uint64_t)clock() * 1000000 / (uint64_t)CLOCKS_PER_SEC;
            }
            break;
        }
        if (--t1 == 0) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
        usleep(1);
    }

    uint64_t elapsed_us = t1 - t0;
    if (elapsed_us == 0) {
        fprintf(stderr, "Invalid elapsed time (0 us)\n");
        return -1;
    }

    /* speed of sound 343 m/s => 0.0343 cm/us; round trip => /2 */
    float distance = (float)elapsed_us * 0.0343f / 2.0f;

    /* HC-SR04 range: 2 cm - 400 cm */
    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    *out_cm = distance;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    /* Allow sensor to settle */
    usleep(SETTLE_US);

    float distance;
    if (measure_distance(trig, echo, &distance) != 0) {
        fprintf(stderr, "Measurement failed\n");
        goto cleanup;
    }

    printf("Distance: %.2f cm\n", distance);
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) {
        gpiod_line_release(trig);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

