#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    uint8_t whoami = 0;
    if (i2c_read_reg8(fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        goto cleanup;
    }
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x68\n", whoami);
        goto cleanup;
    }

    if (i2c_read_reg8(fd, PWR_MGMT_1, &whoami) < 0) {
        fprintf(stderr, "Failed to read PWR_MGMT_1: %s\n", strerror(errno));
        goto cleanup;
    }
    if (i2c_read_reg8(fd, PWR_MGMT_1, &whoami) < 0) {
        fprintf(stderr, "Failed to write PWR_MGMT_1: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (i2c_read_reg16(fd, ACCEL_XOUT_H, &ax) < 0 ||
            i2c_read_reg16(fd, ACCEL_YOUT_H, &ay) < 0 ||
            i2c_read_reg16(fd, ACCEL_ZOUT_H, &az) < 0 ||
            i2c_read_reg16(fd, GYRO_XOUT_H,  &gx) < 0 ||
            i2c_read_reg16(fd, GYRO_YOUT_H,  &gy) < 0 ||
            i2c_read_reg16(fd, GYRO_ZOUT_H,  &gz) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
               ax, ay, az, gx, gy, gz);
        fflush(stdout);
        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return rc;
}

#include <stdio.h>
