#include <gpiod.h>

#define GPIO_2  2
#define GPIO_3  3
#define GPIO_17 17
#define NUM_PINS 3
#define CYCLES 3
#define DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
