#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_CMD_MSB 0x2C
#define MEASURE_CMD_LSB 0x06
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sht31(int fd, float *temperature, float *humidity) {
    if (i2c_write_cmd(fd, MEASURE_CMD_MSB, MEASURE_CMD_LSB) < 0) {
        return -1;
    }

    usleep(20000);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0) {
        return -1;
    }

    uint16_t temp_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t hum_raw  = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
    *humidity    = 100.0f * (float)hum_raw / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f ||
        *humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Invalid sensor data: T=%.2f, H=%.2f\n", *temperature, *humidity);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (g_running) {
        float temperature, humidity;
        if (read_sht31(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read SHT31 data.\n");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

