#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define PIXEL_PIN 18
#define CYCLES 3
#define DELAY_US 500

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int set_pixel(int pin, int red, int green, int blue) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set pin %d as output\n", pin);
        return -1;
    }
    if (gpioWrite(pin, red) < 0) {
        fprintf(stderr, "Error: failed to write red to pin %d\n", pin);
        return -1;
    }
    if (gpioWrite(pin, green) < 0) {
        fprintf(stderr, "Error: failed to write green to pin %d\n", pin);
        return -1;
    }
    if (gpioWrite(pin, blue) < 0) {
        fprintf(stderr, "Error: failed to write blue to pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int rc = EXIT_SUCCESS;
    for (int i = 0; i < CYCLES && running; i++) {
        if (set_pixel(PIXEL_PIN, 1, 0, 0) < 0) {
            rc = EXIT_FAILURE;
            break;
        }
        gpioDelay(DELAY_US);
        if (!running) break;
        if (set_pixel(PIXEL_PIN, 0, 1, 0) < 0) {
            rc = EXIT_FAILURE;
            break;
        }
        gpioDelay(DELAY_US);
        if (!running) break;
        if (set_pixel(PIXEL_PIN, 0, 0, 1) < 0) {
            rc = EXIT_FAILURE;
            break;
        }
        gpioDelay(DELAY_US);
    }

    gpioTerminate();
    return rc;
}

