#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE  "w1_slave"
#define GPIO_PIN 4
#define NUM_READINGS 3
#define SLEEP_SECONDS 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(const char *device_id, float *temperature) {
    char path[256];
    snprintf(path, sizeof(path), "%s/%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line1[256];
    char line2[256];

    if (fgets(line1, sizeof(line1), fp) == NULL) {
        fprintf(stderr, "Error reading first line from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading second line from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device %s\n", device_id);
        return -1;
    }

    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in device %s\n", device_id);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    DIR *dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEVICES_DIR, strerror(errno));
        return 1;
    }

    struct dirent *entry;
    const char *device_id = NULL;

    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            device_id = entry->d_name;
            break;
        }
    }

    closedir(dir);

    if (device_id == NULL) {
        fprintf(stderr, "No DS18B20 sensor found in %s\n", W1_DEVICES_DIR);
        return 1;
    }

    printf("Found DS18B20 sensor: %s\n", device_id);

    for (int i = 0; i < NUM_READINGS && g_running; i++) {
        float temperature;
        if (read_temperature(device_id, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature from sensor %s\n", device_id);
            return 1;
        }

        if (i < NUM_READINGS - 1 && g_running) {
            sleep(SLEEP_SECONDS);
        }
    }

    printf("Exiting.\n");
    return 0;
}

