#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define SENSOR_PIN  24

#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US     30000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL +
           (end->tv_nsec - start->tv_nsec) / 1000LL;
}

static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    struct timespec start, end;
    long long elapsed;

    if (gpiod_line_set_value(trigger, 0) < 0) return -1.0;
    usleep(2);

    if (gpiod_line_set_value(trigger, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) return -1.0;

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed = elapsed_us(&start, &end);
        if (elapsed > TIMEOUT_US) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed = elapsed_us(&start, &end);
        if (elapsed > TIMEOUT_US) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    elapsed = elapsed_us(&start, &end);
    if (elapsed < 0) return -1.0;

    return (float)elapsed * SPEED_OF_SOUND / 2000000.0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL, *sensor = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!trigger || !echo || !sensor) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_input(sensor, "hcsr04") < 0) {
        perror("gpiod_line_request_input (sensor)");
        goto cleanup;
    }

    while (running) {
        float dist = measure_distance(trigger, echo);
        int state = gpiod_line_get_value(sensor);

        if (dist < 0.0) {
            printf("Distance: ERROR, Sensor State: %s\n",
                   state < 0 ? "ERROR" : (state ? "ON" : "OFF"));
        } else {
            printf("Distance: %.2f cm, Sensor State: %s\n",
                   dist, state < 0 ? "ERROR" : (state ? "ON" : "OFF"));
        }
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (sensor) gpiod_line_release(sensor);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

