#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define VALID_MIN 0
#define VALID_MAX 255
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int value) {
    if (value < VALID_MIN || value > VALID_MAX) {
        fprintf(stderr, "Error: PWM value %d out of range [%d, %d] for pin %d\n",
                value, VALID_MIN, VALID_MAX, pin);
        return -1;
    }
    if (gpioPWM(pin, value) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int value = (i + 1) * 50;
            if (set_pwm(pins[i], value) != 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Pin %d: PWM value = %d\n", pins[i], value);
        }
        fflush(stdout);
        usleep(LOOP_DELAY_US);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

