#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define TIMEOUT_US 200

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        usleep(1);
        elapsed++;
        if (elapsed > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    gpiod_line_set_value(line, 0);
    usleep(1000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(line, 1, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(line, 0, TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, TIMEOUT_US) < 0) return -1;
        int j;
        for (j = 0; j < 100; j++) {
            if (gpiod_line_get_value(line) == 0) break;
            usleep(1);
            if (j == 99) return -1;
        }
        data[i / 8] <<= 1;
        if (j > 50) data[i / 8] |= 1;
    }

    if (wait_for_level(line, 0, TIMEOUT_US) < 0) return -1;

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int ret = 1;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
        if (read_dht22(line, &temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            ret = 0;
            break;
        }
        fprintf(stderr, "DHT22 read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
        usleep(2000000);
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

