#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_PIN_4 27
#define CYCLE_DELAY_US 60000000  /* 60 seconds in microseconds */
#define CYCLE_COUNT 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_pwm(int pin, int duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
    }
}

static void apply_cycle(int cycle) {
    int duty;
    switch (cycle) {
        case 1: duty = 0;  break;
        case 2: duty = 128; break;
        case 3: duty = 255; break;
        case 4: duty = 128; break;
        case 5: duty = 0;  break;
        default: duty = 0; break;
    }
    set_pwm(PWM_PIN_1, duty);
    set_pwm(PWM_PIN_2, duty);
    set_pwm(PWM_PIN_3, duty);
    set_pwm(PWM_PIN_4, duty);
    printf("Cycle %d: duty=%d\n", cycle, duty);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    for (int i = 1; i <= CYCLE_COUNT && running; i++) {
        apply_cycle(i);
        if (i < CYCLE_COUNT) {
            /* Sleep in 1-second increments so signals are caught promptly */
            for (int s = 0; s < 60 && running; s++) {
                gpioDelay(1000000);
            }
        }
    }

    /* Ensure all pins are left in a safe state (off) */
    set_pwm(PWM_PIN_1, 0);
    set_pwm(PWM_PIN_2, 0);
    set_pwm(PWM_PIN_3, 0);
    set_pwm(PWM_PIN_4, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

