#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CHIP_NAME "gpiochip0"
#define MAX_RETRIES 3
#define TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, uint32_t timeout_us) {
    uint32_t start = 0;
    while (gpiod_line_get_value(line) != level) {
        if (start >= timeout_us) return -1;
        usleep(1);
        start++;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    gpiod_line_set_value(line, 0);
    usleep(1000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(line, 1, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(line, 0, TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, TIMEOUT_US) < 0) return -1;
        uint32_t start = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (start >= TIMEOUT_US) return -1;
            usleep(1);
            start++;
        }
        data[i / 8] <<= 1;
        if (start > 40) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int ret = 1;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int cycle = 0; cycle < 3 && running; cycle++) {
        if (read_dht22(line, &temperature, &humidity) == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n",
                   cycle + 1, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Cycle %d: Failed to read DHT22 data\n", cycle + 1);
        }
        if (cycle < 2 && running) sleep(60);
    }

    ret = 0;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

