#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_MODE 0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int read_max31855(int fd, float *temperature, float *internal_temp) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) |
                   ((uint32_t)rx[2] << 8) | (uint32_t)rx[3];

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected (bit 16 set)\n");
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = temp_raw * 0.25f;

    int16_t int_temp_raw = (int16_t)((raw >> 4) & 0x0FFF);
    if (int_temp_raw & 0x0800) {
        int_temp_raw |= 0xF000;
    }
    *internal_temp = int_temp_raw * 0.0078125f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = -1;
    if (spi_init(&fd) < 0) {
        return 1;
    }

    float temperature = 0.0f;
    float internal_temp = 0.0f;

    if (read_max31855(fd, &temperature, &internal_temp) < 0) {
        fprintf(stderr, "Failed to read MAX31855 data\n");
        close(fd);
        return 1;
    }

    printf("Temperature: %.2f C\n", temperature);
    printf("Internal Temperature: %.2f C\n", internal_temp);

    close(fd);
    return 0;
}

