#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SENSOR_ID 18
#define STATE_PIN 27

#define TIMEOUT_US 30000
#define SETTLE_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint64_t now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static int wait_level(struct gpiod_line *line, int val, uint64_t timeout_us) {
    uint64_t deadline = now_us() + timeout_us;
    while (running) {
        int r = gpiod_line_get_value(line);
        if (r < 0) return -1;
        if (r == val) return 0;
        if (now_us() >= deadline) return -2;
        usleep(10);
    }
    return -1;
}

static int measure(struct gpiod_line *trig, struct gpiod_line *echo, uint64_t *out_us) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(5);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    if (wait_level(echo, 1, TIMEOUT_US) < 0) return -1;
    uint64_t start = now_us();
    if (wait_level(echo, 0, TIMEOUT_US) < 0) return -1;
    uint64_t end = now_us();
    *out_us = end - start;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *id = gpiod_chip_get_line(chip, SENSOR_ID);
    struct gpiod_line *state = gpiod_chip_get_line(chip, STATE_PIN);
    if (!trig || !echo || !id || !state) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0 ||
        gpiod_line_request_input(echo, "hcsr04") < 0 ||
        gpiod_line_request_input(id, "hcsr04") < 0 ||
        gpiod_line_request_output(state, "hcsr04", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint64_t dist_us = 0;
    if (measure(trig, echo, &dist_us) < 0) {
        fprintf(stderr, "Sensor %d: timeout or error\n", SENSOR_ID);
    } else {
        float dist_cm = dist_us / 58.0f;
        printf("Sensor %d: distance = %.2f cm\n", SENSOR_ID, dist_cm);
    }

    gpiod_line_set_value(state, 1);
    usleep(SETTLE_US);
    gpiod_line_set_value(state, 0);

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(id);
    gpiod_line_release(state);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

