static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x58)\n", id);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;

    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    *temperature = (float)raw_temperature / 100.0f;
    *pressure = (float)raw_pressure / 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3 && g_running; i++) {
        float temperature, pressure;
        if (bmp280_read(fd, &temperature, &pressure) < 0) {
            fprintf(stderr, "Error reading BMP280 data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
        sleep(1);
    }

    close(fd);
    return 0;
}

