#include <string.h>

#define VEML7700_ADDR 0x10
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(fd, 0x00, 0x00) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t ambient;
        if (i2c_read_reg16(fd, 0x04, &ambient) == 0) {
            printf("Ambient Light: %u lux\n", ambient);
        } else {
            fprintf(stderr, "Failed to read ambient light\n");
        }
        fflush(stdout);
        usleep(500000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define BAUD_RATE B115200
#define DEVICE "/dev/ttyS0"
#define READ_TIMEOUT_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_line(int fd, char *buf, size_t buflen) {
    size_t idx = 0;
    while (idx < buflen - 1) {
        if (!g_running) return -1;

        char ch;
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(10000);
                continue;
            }
            return -1;
        }
        if (n == 0) {
            usleep(10000);
            continue;
        }
        if (ch == '\n') break;
        buf[idx++] = ch;
    }
    buf[idx] = '\0';
    return (int)idx;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = init_uart(DEVICE);
    if (fd < 0) return 1;

    printf("UART initialized on %s at 115200 baud.\n", DEVICE);

    while (g_running) {
        char line[256];
        int len = read_line(fd, line, sizeof(line));
        if (len < 0) {
            if (!g_running) break;
            fprintf(stderr, "Read error: %s\n", strerror(errno));
            break;
        }
        if (len == 0) {
            fprintf(stderr, "Device not responding (no data within %d s).\n", READ_TIMEOUT_SEC);
            break;
        }
        printf("Received: %s\n", line);
        fflush(stdout);
        usleep(100000);
    }

    if (fd >= 0) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  200000  /* 200 ms timeout for echo */
#define SAMPLE_HZ   2       /* 0.5 s between readings */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure distance in mm. Returns -1 on timeout or invalid reading.
 * Uses libgpiod line values (0 = low, 1 = high).
 */
static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    struct timespec ts;
    uint64_t start_tick = 0, end_tick = 0;
    int val;

    /* Ensure trigger is low for a clean start */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set trigger low");
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("set trigger high");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set trigger low");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    ts.tv_sec = 0;
    ts.tv_nsec = 1000000; /* 1 ms */
    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("read echo");
            return -1;
        }
        if (val == 1) {
            start_tick = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
            break;
        }
        if (nanosleep(&ts, &ts) < 0) {
            if (errno == EINTR) continue;
            perror("nanosleep");
            return -1;
        }
    }
    if (!running) return -1;

    /* Wait for echo falling edge (timeout) */
    ts.tv_sec = 0;
    ts.tv_nsec = 1000000;
    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("read echo");
            return -1;
        }
        if (val == 0) {
