#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN  4
#define ECHO_PIN     17
#define SENSOR_PIN   18
#define TIMEOUT_US   30000   /* 30 ms timeout for echo (max range ~5 m) */
#define LOOP_DELAY_US 100000 /* 0.1 s between readings */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the pulse width in microseconds, or -1 on timeout / error.
 */
static long measure_echo(struct gpiod_line *echo)
{
    struct timespec ts_start, ts_now;
    long elapsed_us;

    /* Wait for echo to go HIGH (start of pulse) */
    if (gpiod_line_get_value(echo) != 1) {
        return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    /* Poll for echo HIGH with timeout */
    while (gpiod_line_get_value(echo) != 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L
                   + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1;
        }
    }

    /* Wait for echo to go LOW (end of pulse) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (gpiod_line_get_value(echo) != 0) {
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L
                   + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &ts_now);
    return (ts_now.tv_sec - ts_start.tv_sec) * 1000000L
         + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    struct gpiod_line *sensor = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo    = gpiod_chip_get_line(chip, ECHO_PIN);
    sensor  = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!trigger || !echo || !sensor) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request lines with appropriate directions */
    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_input(sensor, "hcsr04-sensor") < 0) {
        perror("gpiod_line_request_input (sensor)");
        goto cleanup;
    }

    /* Allow sensor to settle */
    usleep(100000);

    while (running) {
        /* Send 10 us trigger pulse */
        if (gpiod_line_set_value(trigger, 1) < 0) {
            perror("gpiod_line_set_value (trigger HIGH)");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value (trigger LOW)");
            goto cleanup;
        }

        long pulse_us = measure_echo(echo);

        if (pulse_us < 0) {
            fprintf(stderr, "Error: Echo timeout or read error\n");
        } else {
            /* Convert microseconds to centimeters (speed of sound ~343 m/s) */
            float distance_cm = (float)pulse_us * 0.0343f / 2.0f;
            int sensor_state = gpiod_line_get_value(sensor);
            if (sensor_state < 0) {
                perror("gpiod_line_get_value (sensor)");
                goto cleanup;
            }
            printf("Distance: %.2f cm, Sensor State: %d\n", distance_cm, sensor_state);
        }

        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (trigger) gpiod_line_release(trigger);
    if (echo)    gpiod_line_release(echo);
    if (sensor)  gpiod_line_release(sensor);
    if (chip)    gpiod_chip_close(chip);

    return ret;
}

