#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t id = 0;
    if (i2c_read_reg16(fd, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "TCS34725 not detected at address 0x%02X\n", TCS34725_ADDRESS);
        close(fd);
        return 1;
    }
    if ((id & 0xFF) != 0x44) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x44)\n", id & 0xFF);
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) {
        close(fd);
        return 1;
    }
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) {
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t c, r, g, b;
        if (i2c_read_reg16(fd, TCS34725_CDATA, &c) < 0 ||
            i2c_read_reg16(fd, TCS34725_RDATA, &r) < 0 ||
            i2c_read_reg16(fd, TCS34725_GDATA, &g) < 0 ||
            i2c_read_reg16(fd, TCS34725_BDATA, &b) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
        } else {
            printf("C: %5u  R: %5u  G: %5u  B: %5u\n", c, r, g, b);
        }
        usleep(500000);
    }

    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

