#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define STATE_PIN   24
#define TIMEOUT_US  30000  /* 30 ms timeout for echo */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static uint64_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static int wait_level(struct gpiod_line *line, int val, uint64_t deadline_us)
{
    while (running) {
        int v = gpiod_line_get_value(line);
        if (v < 0)
            return -1;
        if (v == val)
            return 0;
        if (now_us() >= deadline_us)
            return -2;  /* timeout */
        usleep(10);
    }
    return -1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *state = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    state = gpiod_chip_get_line(chip, STATE_PIN);
    if (!trig || !echo || !state) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("request trig output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        perror("request echo input");
        goto cleanup;
    }
    if (gpiod_line_request_input(state, "hcsr04") < 0) {
        perror("request state input");
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set trig low");
        goto cleanup;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("set trig high");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set trig low");
        goto cleanup;
    }

    uint64_t deadline = now_us() + TIMEOUT_US;
    if (wait_level(echo, 1, deadline) != 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        goto cleanup;
    }

    uint64_t t0 = now_us();
    if (wait_level(echo, 0, deadline) != 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        goto cleanup;
    }
    uint64_t t1 = now_us();

    uint64_t elapsed = t1 - t0;
    double distance = (double)elapsed * 0.0343 / 2.0;  /* cm */

    int s = gpiod_line_get_value(state);
    if (s < 0) {
        perror("get state");
        goto cleanup;
    }

    printf("Distance: %.2f cm, State: %s\n", distance, s ? "ON" : "OFF");
    rc = EXIT_SUCCESS;

cleanup:
    if (trig)  gpiod_line_release(trig);
    if (echo)  gpiod_line_release(echo);
    if (state) gpiod_line_release(state);
    if (chip)  gpiod_chip_close(chip);
    return rc;
}

