#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 200000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGINT handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 0;
    int direction = 1;

    while (running) {
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", PWM_PIN);
            break;
        }
        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);

        duty += direction;
        if (duty >= PWM_RANGE) {
            duty = PWM_RANGE;
            direction = -1;
        } else if (duty <= 0) {
            duty = 0;
            direction = 1;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

