        perror("gpiod_line_set_value 18");
        goto cleanup;
    }

    printf("GPIO 17: HIGH, GPIO 18: HIGH\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24
#define CONSUMER "blink"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {GPIO_18, GPIO_23, GPIO_24};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read line %d\n", pins[i]);
                goto cleanup;
            }
            val = !val;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set line %d\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %d: %d\n", pins[i], val);
        }
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define TEMP_OUT_H   0x41
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    int fd = -1;
    int16_t ax, ay, az, gx, gy, gz, temp;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    if (i2c_read_reg8(fd, PWR_MGMT_1, (uint8_t *)&temp) < 0) {
        perror("Failed to wake MPU6050");
        close(fd);
        return 1;
    }
    if (i2c_read_reg8(fd, PWR_MGMT_1, (uint8_t *)&temp) < 0) {
        perror("Failed to wake MPU6050");
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_read_reg16(fd, ACCEL_XOUT_H, &ax) < 0 ||
            i2c_read_reg16(fd, ACCEL_YOUT_H, &ay) < 0 ||
            i2c_read_reg16(fd, ACCEL_ZOUT_H, &az) < 0 ||
            i2c_read_reg16(fd, TEMP_OUT_H, &temp) < 0 ||
            i2c_read_reg16(fd, GYRO_XOUT_H, &gx) < 0 ||
            i2c_read_reg16(fd, GYRO_YOUT_H, &gy) < 0 ||
            i2c_read_reg16(fd, GYRO_ZOUT_H, &gz) < 0) {
            perror("I2C read error");
            break;
        }

        printf("Accel: X=%d, Y=%d, Z=%d, Temp: %d, Gyro: X=%d, Y=%d, Z=%d\n",
               ax, ay, az, temp, gx, gy, gz);
        fflush(stdout);
        sleep(1);
    }

    if (fd >= 0) close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define INTERVAL_SEC 0
#define INTERVAL_NSEC 600000000

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "blink", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE);
        fflush(stdout);

        struct timespec ts = { INTERVAL_SEC, INTERVAL_NSEC };
        while (nanosleep(&ts, &ts) == -1 && running && errno == EINTR) {
            /* interrupted by signal; loop to re-check running */
        }
        if (!running) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE);
        fflush(stdout);

        ts = (struct timespec) { INTERVAL_SEC, INTERVAL_NSEC };
        while (nanosleep(&ts, &ts) == -1 && running && errno == EINTR) {
            /* interrupted by signal; loop to re-check running */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}
